CREATE OR REPLACE PACKAGE BODY bench_b1 AS

  FUNCTION run RETURN NUMBER IS
    l_t0 NUMBER;
    l_t1 NUMBER;
  BEGIN
    l_t0 := dbms_utility.get_time();
    FOR r IN (
      select user_id, movie_id, rating, ts from ml_ratings_src
    ) LOOP
      insert into ml_ratings_b1(user_id, movie_id, rating, ts)
            values (r.user_id, r.movie_id, r.rating, r.ts);
    END LOOP;
    l_t1 := dbms_utility.get_time();
    RETURN ((l_t1 - l_t0) * 10);
  END run;
END bench_b1;
